    <g id="hit" transform="${H.transform}">${lit.map(([p, id]) => `<polygon points="${pts(p)}" fill="transparent" stroke="transparent" stroke-width="24" data-entity="${id}" style="cursor:pointer"><title>${esc(lightName(id))}</title></polygon>`).join('')}
    </g>
